commands.command:
/bin/bash -lc 'mkdir -p checks/wording-review
npm start -- --hostname 127.0.0.1 --port 3012 > /tmp/storyfolio-local-setup/wording-server.log 2>&1 &
wording_server_pid=$!
trap '"'kill \""'$wording_server_pid" 2>/dev/null || true'"' EXIT
node -e 'for(let i=0;i<100;i++){try{if((await fetch(\"http://127.0.0.1:3012\")).ok)break}catch{};await new Promise(r=>setTimeout(r,200))}'
node --input-type=module <<'JS'
import { chromium } from 'playwright-core';
import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
const base='http://127.0.0.1:3012';
const browser=await chromium.launch({executablePath:'/tmp/chromium',args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist']});
const results=[];
try {
 const context=await browser.newContext({viewport:{width:1440,height:900},reducedMotion:'reduce'});
 const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 for(const path of ['/','/cv','/wording','/downloads/dawit-bekele-cv.html','/icon.svg','/opengraph-image.png']){
  const response=await fetch(base+path);assert.equal(response.status,200);results.push({path,status:response.status});
 }
 await page.goto(base+'/wording');assert.equal(await page.locator('.wording-option').count(),3);
 await page.screenshot({path:'checks/wording-review/complete-options.png',fullPage:true});
 for(const id of ['1','2','3']){
  await page.goto(base+'/preview?look=night&words='+id);
  await page.waitForFunction(()=>window.__stitch?.ready);
  assert.equal(await page.evaluate(()=>window.__stitch.mix),'map,map,map,map,map,map,map,map');
  for(const [part,at]of [['opening',0],['close',6]]){
   await page.evaluate(s=>scrollTo(0,window.__stitch.top()+s*window.__stitch.unit()),at);
   await page.waitForTimeout(350);
   await page.screenshot({path:"'`checks/wording-review/${id}-${part}.png`});
  }
 }
 assert.deepEqual(errors,[]);
 writeFileSync('"'checks/wording-review/report.json',JSON.stringify({results,options:3,wholeBeatScreenshots:6,pageErrors:errors},null,2));
 console.log('Passed: six local routes, three whole-beat options, map/night previews, no page errors.');
}finally{await browser.close();}
JS"
